def num(v):
    # JSON booleans and nonfinite values are not financial measurements.
    if type(v) not in (int, float, str) or isinstance(v, str) and len(v) > 512:
        return None
    try:
        value = float(v)
        return value if math.isfinite(value) else None
    except (ValueError, TypeError, OverflowError):
        return None


def first_num(*values):
    """Prefer the first available numeric observation, including genuine zero."""
    for value in values:
        result = num(value)
        if result is not None:
            return result
    return None

